import java.util.Scanner;

public class Main {
    static final long mod = 1000000007;

    static class M {
        long[][] s;
        int n;

        M(int size) {
            s = new long[size][size];
            n = size;
        }

        static M multiply(M a, M b) {
            M c = new M(a.n);
            for (int i = 0; i < a.n; i++) {
                for (int j = 0; j < a.n; j++) {
                    c.s[i][j] = 0;
                    for (int k = 0; k < a.n; k++) {
                        c.s[i][j] += a.s[i][k] * b.s[k][j];
                        c.s[i][j] %= mod;
                    }
                }
            }
            return c;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();

        int size = (int) (m + 1);
        M[][] bi = new M[65][65];

        for (int i = 0; i <= 64; i++) {
            for (int j = 0; j <= 64; j++) {
                bi[i][j] = new M(size);
            }
        }

        M I = new M(size);
        bi[0][0].n = size;
        for (int i = 0; i < size; i++) {
            bi[0][0].s[i][i] = 1;
            bi[0][0].s[0][i] = 1;
        }

        long x = 0, y = 1, z = 0, add = 0;
        while (y * m <= n) {
            y *= m;
            x++;
        }

        for (long t = 0; t <= x; t++) {
            if (t != 0) {
                bi[(int) t][0] = bi[(int) t - 1][0];
                for (int i = 1; i < m; i++) {
                    bi[(int) t][0] = M.multiply(bi[(int) t][0], bi[(int) t - 1][i]);
                }
            }
            for (int i = 1; i < m; i++) {
                bi[(int) t][i] = bi[(int) t][i - 1];
                for (int j = m - 2; j >= 0; j--) {
                    for (int k = 0; k <= m; k++) {
                        long temp = bi[(int) t][i].s[j][k];
                        bi[(int) t][i].s[j][k] = bi[(int) t][i].s[j + 1][k];
                        bi[(int) t][i].s[j + 1][k] = temp;
                    }
                }
                for (int j = m - 2; j >= 0; j--) {
                    for (int k = 0; k <= m; k++) {
                        long temp = bi[(int) t][i].s[k][j];
                        bi[(int) t][i].s[k][j] = bi[(int) t][i].s[k][j + 1];
                        bi[(int) t][i].s[k][j + 1] = temp;
                    }
                }
            }
        }

        for (int i = 0; i <= m; i++) {
            I.n = size;
            for (int j = 0; j < size; j++) {
                I.s[j][j] = 1;
            }
        }

        while (add < n) {
            if (add <= n - y) {
                add += y;
                I = M.multiply(I, bi[(int) x][(int) z]);
                z = (z + 1) % m;
            } else {
                y /= m;
                x--;
            }
        }

        long ans = 0;
        for (int i = 0; i <= m; i++) {
            ans = (ans + I.s[i][(int) m]) % mod;
        }
        System.out.println(ans);
        sc.close();
    }
}
